// ============================================================================
// ANTIBIOTIC QUEST — Drug (weapon) definitions
// ----------------------------------------------------------------------------
// Each drug is a weapon. `spectrum` maps bug TAGS -> damage multiplier.
// Bug tags are ordered general -> specific; resolution takes the LAST
// matching tag, so specific entries override general ones.
// `blockedBy` maps a resistance mechanism -> reason text (or {mult, text}).
// `noCover` gives educational reasons for specific tags with 0 coverage.
// `flags`: bbb (true | 'inflamed' | false), urineOnly, lungBlocked, needsO2,
//          anaerobeOnly, intracellular (reaches intracellular bugs), fungal.
// `proj`: projectile archetype + tuning.
// `tier`: stewardship breadth 1 (narrow) .. 4 (last resort, limited doses).
// ============================================================================

export const TARGETS = {
  wall:   { name: 'Cell wall synthesis',        icon: 'wall',   color: '#6fd6ff', desc: 'Blocks peptidoglycan assembly (PBPs / D-Ala-D-Ala). Bacteria lyse under their own osmotic pressure. Useless against organisms with no wall.' },
  r30:    { name: 'Protein synthesis (30S)',    icon: 'r30',    color: '#ffd166', desc: 'Binds the 30S ribosomal subunit. Aminoglycosides cause misreading (bactericidal); tetracyclines block tRNA docking (bacteriostatic).' },
  r50:    { name: 'Protein synthesis (50S)',    icon: 'r50',    color: '#ffb347', desc: 'Binds the 50S subunit: macrolides & clindamycin block translocation; linezolid blocks initiation. Mostly bacteriostatic.' },
  dna:    { name: 'DNA replication / integrity', icon: 'dna',   color: '#c77dff', desc: 'Fluoroquinolones jam DNA gyrase / topoisomerase IV; metronidazole & nitrofurantoin shred DNA with reactive radicals.' },
  rna:    { name: 'RNA polymerase',             icon: 'rna',    color: '#ff7eb6', desc: 'Rifamycins bind the β subunit (rpoB) of bacterial RNA polymerase and stop transcription.' },
  folate: { name: 'Folate synthesis',           icon: 'folate', color: '#9bf6a7', desc: 'Sequential blockade: sulfamethoxazole inhibits dihydropteroate synthase, trimethoprim inhibits DHFR. No folate → no nucleotides.' },
  membrane:{ name: 'Cell membrane',             icon: 'membrane', color: '#ff6b6b', desc: 'Daptomycin depolarizes gram-positive membranes; polymyxins act as detergents on the gram-negative outer membrane (LPS).' },
  myco:   { name: 'Mycolic acid / TB-specific', icon: 'myco',   color: '#f4a261', desc: 'Isoniazid blocks mycolic acid synthesis, ethambutol blocks arabinogalactan, pyrazinamide disrupts membrane energetics in acidic phagosomes.' },
  fungal: { name: 'Ergosterol (fungal membrane)', icon: 'fungal', color: '#a0e7a0', desc: 'Azoles block ergosterol synthesis. Bacteria have no ergosterol — and fungi have no peptidoglycan — so the two drug families never cross over.' },
};

