export const DRUG_BY_ID = Object.fromEntries(DRUGS.map((d) => [d.id, d]));

// Stewardship: microbiome cost per shot (how much "collateral damage" a weapon does)
export function microbiomeCost(drug) {
  const base = [0, 0.0, 0.25, 0.6, 0.35][drug.tier] ?? 0.3;
  return base * (drug.flags?.cdiffRisk || 1);
}

